"""Measure precision/recall over the fixture corpus. Regenerated by `make bench`."""
import os

from mcp_guard.scan import run_scan

# Repo root is one level up from scripts/, so this runs from any cwd.
REPO = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))

# Ground truth: the vulnerabilities each fixture is built to contain.
TRUTH = {
    "clean-server":      set(),
    "not-a-server":      set(),
    "instant-exit":      set(),
    "always-error-live": set(),
    "vulnerable-server": {"cmd-injection", "path-traversal", "hardcoded-secret"},
    "python-server":     {"cmd-injection", "path-traversal"},
    "ts-server":         {"prompt-injection"},
    "docker-server":     {"container-root", "world-writable"},
}
MAP = {
    "MCPG-DYN-CMDEXEC": "cmd-injection", "MCPG-JS-SHELL-TAINT": "cmd-injection",
    "MCPG-PY-SHELL-TAINT": "cmd-injection",
    "MCPG-DYN-PATHTRAVERSAL": "path-traversal",
    "MCPG-JS-PATH-TAINT": "path-traversal", "MCPG-PY-PATH-TAINT": "path-traversal",
    "MCPG-SECRET-HARDCODED": "hardcoded-secret",
    "MCPG-MCP-PROMPT-INJECTION-SURFACE": "prompt-injection",
    "MCPG-DOCKER-ROOT": "container-root",
    "MCPG-DOCKER-CHMOD777": "world-writable",
}

TP = 0
FP = 0
FN = 0
rows=[]
for fx, truth in TRUTH.items():
    r,acq = run_scan(os.path.join(REPO, "tests", "fixtures", fx), allow_execute=True,
                     skip_install=True, deps_enabled=False)
    if acq:
        acq.cleanup()
    found = set()
    unmapped = 0
    for f in r.findings:
        c = MAP.get(f.rule_id)
        if c:
            found.add(c)
        else:
            unmapped += 1
    tp = len(found & truth)
    fp = len(found - truth) + unmapped
    fn = len(truth - found)
    TP += tp
    FP += fp
    FN += fn
    rows.append((fx, len(r.findings), tp, fp, fn, ",".join(sorted(found)) or "-"))

print(f"{'fixture':<20}{'n':>3}{'TP':>4}{'FP':>4}{'FN':>4}  categories")
print("-"*72)
for r in rows:
    print(f"{r[0]:<20}{r[1]:>3}{r[2]:>4}{r[3]:>4}{r[4]:>4}  {r[5]}")
print("-"*72)
prec = TP/(TP+FP) if TP+FP else 1.0
rec  = TP/(TP+FN) if TP+FN else 1.0
print(f"{'TOTAL':<20}{'':>3}{TP:>4}{FP:>4}{FN:>4}")
print(f"precision = {TP}/{TP+FP} = {prec*100:.1f}%   recall = {TP}/{TP+FN} = {rec*100:.1f}%")
